'use strict';
(() => {
 const reader=document.getElementById('reader'),toolbar=document.getElementById('annotation-tools'),dialog=document.getElementById('note-editor'),input=document.getElementById('note-text');
 const KEY='cet6-annotations-full-v1',NS='http://www.w3.org/2000/svg';let day=1,tool='read',data={strokes:[],notes:[]},history=[],drawing=null,noteAnchor=null,saveFailed=false,loaded=false;
 function svg(tag,attrs={}){const n=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);return n;}
 function save(){if(loaded)try{localStorage.setItem(KEY+':'+day,JSON.stringify(data));saveFailed=false;}catch{saveFailed=true;}document.getElementById('annotation-status').textContent=saveFailed?'保存失败，请检查浏览器存储空间':tool==='read'?'':tool==='note'?'点击正文添加文字批注':'书写模式 · 切换「阅读」可滚动查词';toolbar.querySelector('[data-action="undo"]').disabled=!history.length;}
 function snapshot(){history.push(JSON.stringify(data));if(history.length>60)history.shift();}
 function setTool(value){tool=value;reader.dataset.annotationTool=value;for(const b of toolbar.querySelectorAll('[data-tool]'))b.setAttribute('aria-pressed',String(b.dataset.tool===value));save();}
 function pathD(points){return points.map((p,i)=>(i?'L':'M')+p.map(n=>n.toFixed(2)).join(' ')).join(' ');}
 function renderStroke(stroke,layer){const p=svg('path',{d:pathD(stroke.points),fill:'none',stroke:'#111','stroke-width':stroke.tool==='marker'?14:2.3,'stroke-opacity':stroke.tool==='marker'?.15:1,'stroke-linecap':'round','stroke-linejoin':'round','vector-effect':'non-scaling-stroke'});p.dataset.stroke=stroke.id;layer.append(p);return p;}
 function paragraphLayers(){return [...reader.querySelectorAll('.paragraph')];}
 function rebuild(){for(const [i,p] of paragraphLayers().entries()){p.querySelector('.ink-layer')?.remove();p.querySelector('.margin-notes')?.remove();p.dataset.paragraph=i;const layer=svg('svg',{viewBox:'0 0 1000 1000',preserveAspectRatio:'none','aria-hidden':'true'});layer.classList.add('ink-layer');for(const s of data.strokes.filter(s=>s.paragraph===i))renderStroke(s,layer);p.append(layer);const notes=data.notes.filter(n=>n.paragraph===i);if(notes.length){const list=document.createElement('div');list.className='margin-notes';for(const note of notes){const b=document.createElement('button');b.type='button';b.className='annotation-note';b.dataset.note=note.id;b.textContent=note.anchor+' · '+note.text;b.title='编辑文字批注';list.append(b);}p.append(list);}}
 setTool(tool);}
 function id(){return Date.now().toString(36)+Math.random().toString(36).slice(2,8);}
 function point(event,layer){const r=layer.getBoundingClientRect();return [Math.max(0,Math.min(1000,(event.clientX-r.left)/r.width*1000)),Math.max(0,Math.min(1000,(event.clientY-r.top)/r.height*1000))];}
 reader.addEventListener('pointerdown',event=>{if(!['pen','marker','eraser'].includes(tool)||event.button!==0)return;const layer=event.target.closest('.ink-layer');if(!layer)return;event.preventDefault();if(tool==='eraser'){const stroke=event.target.closest('[data-stroke]');if(stroke){snapshot();data.strokes=data.strokes.filter(s=>s.id!==stroke.dataset.stroke);rebuild();save();}return;}
 const stroke={id:id(),paragraph:Number(layer.parentElement.dataset.paragraph),tool,points:[point(event,layer)]};const path=renderStroke(stroke,layer);drawing={pointer:event.pointerId,stroke,path,layer};layer.setPointerCapture(event.pointerId);
 });
 reader.addEventListener('pointermove',event=>{if(!drawing||event.pointerId!==drawing.pointer)return;event.preventDefault();const samples=event.getCoalescedEvents?.()||[event];for(const e of samples)drawing.stroke.points.push(point(e,drawing.layer));drawing.path.setAttribute('d',pathD(drawing.stroke.points));});
 function finish(event){if(!drawing||event.pointerId!==drawing.pointer)return;const d=drawing;drawing=null;if(d.stroke.points.length===1)d.stroke.points.push([d.stroke.points[0][0]+.1,d.stroke.points[0][1]+.1]);snapshot();data.strokes.push(d.stroke);d.path.setAttribute('d',pathD(d.stroke.points));save();}
 reader.addEventListener('pointerup',finish);reader.addEventListener('pointercancel',finish);
 function openNote(paragraph,anchor,note=null){noteAnchor={paragraph,anchor,id:note?.id||id()};document.getElementById('note-anchor').textContent=anchor;input.value=note?.text||'';document.getElementById('note-delete').hidden=!note;dialog.showModal();document.body.classList.add('modal-open');input.focus();}
 reader.addEventListener('click',event=>{const note=event.target.closest('[data-note]');if(note){event.preventDefault();event.stopImmediatePropagation();const n=data.notes.find(n=>n.id===note.dataset.note);if(n)openNote(n.paragraph,n.anchor,n);return;}if(tool==='read')return;event.preventDefault();event.stopImmediatePropagation();if(tool==='note'){const p=event.target.closest('.paragraph');if(p){const word=event.target.closest('[data-word]');openNote(Number(p.dataset.paragraph),word?.dataset.word||'段落批注');}}},true);
 toolbar.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.tool)setTool(b.dataset.tool);if(b.dataset.action==='undo'&&history.length){data=JSON.parse(history.pop());rebuild();save();}});
 document.getElementById('note-save').onclick=()=>{if(!noteAnchor)return;const text=input.value.trim();if(!text)return; snapshot();data.notes=data.notes.filter(n=>n.id!==noteAnchor.id);data.notes.push({...noteAnchor,text});rebuild();save();dialog.close();};
 document.getElementById('note-delete').onclick=()=>{snapshot();data.notes=data.notes.filter(n=>n.id!==noteAnchor.id);rebuild();save();dialog.close();};
 window.addEventListener('cet6:article',event=>{day=event.detail.day;history=[];drawing=null;try{const stored=JSON.parse(localStorage.getItem(KEY+':'+day));data=stored&&Array.isArray(stored.strokes)&&Array.isArray(stored.notes)?stored:{strokes:[],notes:[]};}catch{data={strokes:[],notes:[]};}loaded=true;rebuild();});
 setTool('read');
})();
